const url = $json.url || '';
const text = $json.text || '';
const kind = $json.kind || 'html';
const pdfUrl = $json.pdfUrl || null;

let messages;

if (kind === 'pdf' && pdfUrl) {
  // URL-based PDF document source — Claude reads the PDF directly from URL
  // Supported in claude-haiku-4-5-20251001 and later models
  messages = [{
    role: 'user',
    content: [
      {
        type: 'document',
        source: {
          type: 'url',
          url: pdfUrl
        }
      },
      {
        type: 'text',
        text: 'Este es un boletín oficial o documento municipal argentino. Extrae TODOS los actos administrativos: contratos, licitaciones, compras directas, decretos, resoluciones, subsidios y obras públicas. Para cada uno extrae: número de decreto/resolución/licitación, nombre del proveedor o empresa, monto en ARS, fecha, descripción del objeto. Responde SOLO con JSON válido sin markdown: { "doc": { "url": "", "title": "", "date": "", "type": "boletin_oficial" }, "procedures": [ { "id": "", "title": "", "supplier": "", "amount": null, "currency": "ARS", "date": "", "type": "licitacion|contratacion_directa|compra_menor|obra_publica|subsidio|decreto|resolucion", "evidence_quote": "" } ], "actors": [ { "name": "", "role": "" } ], "fragments": [ { "quote": "", "relevance": "" } ] }. Si no hay datos devuelve listas vacías.'
      }
    ]
  }];
} else {
  messages = [{
    role: 'user',
    content: 'URL: ' + url + '\n\nContenido (primeros 10000 chars):\n' + text.slice(0, 10000)
  }];
}

const body = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 4000,
  system: 'Eres un extractor de datos para analisis anticorrupcion municipal argentina. Extrae datos del documento y responde SOLO con JSON valido: { "doc": { "url": "", "title": "", "date": "", "type": "" }, "procedures": [ { "id": "", "title": "", "supplier": "", "amount": null, "currency": "ARS", "date": "", "type": "", "evidence_quote": "" } ], "actors": [ { "name": "", "role": "" } ], "fragments": [ { "quote": "", "relevance": "" } ] }. Sin markdown.',
  messages: messages
};

return JSON.stringify(body);
